// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: playfairFamily } = loadPlayfair();



export type ElegantHookTitleProps = Record<string, any>;

const ElegantHookTitle: React.FC<ElegantHookTitleProps> = ({
  backgroundColor = "#FAF8F5",
  transparentBackground = false,
  durationInSeconds = 5,
  introText = "This is the exact",
  keyword1 = "ROADMAP",
  midText = "to a $20K a month",
  keyword2 = "Beauty business",
  textColor = "#2C2A29",
  accentColor = "#A87B51",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Continuous subtle zoom for the entire composition
  const containerScale = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [1, 1.05],
    { extrapolateRight: "clamp" }
  );

  // Configuration for each text layer to create a staggered, elegant entrance
  // "bold" type added for Intro and Mid texts as requested
  const elements = [
    { text: introText, type: "bold", delay: 0 },
    { text: keyword1, type: "accent-bold", delay: 15 },
    { text: midText, type: "bold", delay: 35 },
    { text: keyword2, type: "accent-serif", delay: 50 },
  ];

  // Smooth S-Curve roadmap path flowing across the screen
  const roadmapPath = `
    M ${width * 0.2} ${height * 1.1}
    C ${width * 0.8} ${height * 0.8},
      ${width * 0.8} ${height * 0.6},
      ${width * 0.5} ${height * 0.5}
    C ${width * 0.2} ${height * 0.4},
      ${width * 0.2} ${height * 0.2},
      ${width * 0.8} ${height * -0.1}
  `;

  // Draw offset for the background roadmap path, completing at 80% of the video length
  const drawOffset = interpolate(
    frame,
    [0, fps * (durationInSeconds * 0.8)],
    [100, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Background Roadmap Animation */}
      <svg
        width="100%"
        height="100%"
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          zIndex: 0,
        }}
      >
        <defs>
          <mask id="roadmap-mask">
            {/* Mask path that "draws" in over time using pathLength logic */}
            <path
              d={roadmapPath}
              stroke="white"
              strokeWidth={width * 0.1}
              fill="none"
              strokeDasharray="100"
              strokeDashoffset={drawOffset}
              pathLength="100"
              strokeLinecap="round"
            />
          </mask>
        </defs>
        
        {/* Subtle continuous background line */}
        <path
          d={roadmapPath}
          stroke={accentColor}
          strokeWidth={width * 0.003}
          fill="none"
          opacity={0.15}
        />
        
        {/* Animated dashed roadmap line revealed by the mask */}
        <path
          d={roadmapPath}
          stroke={accentColor}
          strokeWidth={width * 0.008}
          fill="none"
          strokeDasharray={`${width * 0.025} ${width * 0.025}`}
          strokeLinecap="round"
          mask="url(#roadmap-mask)"
          opacity={0.5}
        />
      </svg>

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          width: "85%",
          textAlign: "center",
          transform: `scale(${containerScale})`,
          transition: "none",
          position: "relative",
          zIndex: 1, // Ensure text stays above the roadmap
        }}
      >
        {elements.map((el, i) => {
          // Cinematic spring physics for smooth, luxurious motion
          const progress = spring({
            frame: frame - el.delay,
            fps,
            config: { damping: 16, mass: 0.8, stiffness: 70 },
          });

          const yOffset = interpolate(progress, [0, 1], [40, 0]);
          const opacity = interpolate(progress, [0, 1], [0, 1]);
          const blur = interpolate(progress, [0, 1], [20, 0]);
          
          // Slight scale-down pop for accents to give them weight
          const elementScale = el.type.includes("accent")
            ? interpolate(progress, [0, 1], [0.95, 1])
            : 1;

          const isSerif = el.type === "accent-serif";
          const isBoldAccent = el.type === "accent-bold";
          const isRegularBold = el.type === "bold";

          return (
            <div
              key={i}
              style={{
                opacity,
                transform: `translateY(${yOffset}px) scale(${elementScale})`,
                filter: `blur(${blur}px)`,
                fontFamily: isSerif ? playfairFamily : interFamily,
                fontSize: isSerif
                  ? width * 0.14
                  : isBoldAccent
                  ? width * 0.12
                  : width * 0.055,
                fontWeight: isSerif ? 500 : isBoldAccent ? 900 : isRegularBold ? 700 : 400,
                fontStyle: isSerif ? "italic" : "normal",
                color: isSerif || isBoldAccent ? accentColor : textColor,
                textTransform: isBoldAccent ? "uppercase" : "none",
                lineHeight: 1.15,
                letterSpacing: isBoldAccent ? "0.05em" : "0em",
                margin: isBoldAccent
                  ? `${height * 0.015}px 0`
                  : `${height * 0.008}px 0`,
                transition: "none",
                willChange: "transform, opacity, filter",
              }}
            >
              {el.text}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default ElegantHookTitle;